	var spot *bool = this.SafeBool(market, "spot", false)
	var quoteVolume any = Ternary((spot != nil && *spot == true), this.SafeString(ticker, "volCurrency24h"), nil)
	var baseVolume *string = this.SafeString(ticker, "vol24h")
