func (this *Blofin) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetch trades (response similar for REST & WS)
	//
	//   {
	//       "tradeId": "3263934920",
	//       "instId": "LTC-USDT",
	//       "price": "67.87",
	//       "size": "1",
	//       "side": "buy",
	//       "ts": "1707232020854"
	//   }
	//
	// my trades
	//   {
	//       "instId": "LTC-USDT",
	//       "tradeId": "1440847",
	//       "orderId": "2075705202",
	//       "fillPrice": "67.850000000000000000",
	//       "fillSize": "1.000000000000000000",
	//       "fillPnl": "0.000000000000000000",
	//       "side": "buy",
	//       "positionSide": "net",
	//       "fee": "0.040710000000000000",
	//       "ts": "1707224678878",
	//       "brokerId": ""
	//   }
	//
	// fetchMyTrades spot
	//     {
	//         "instId": "DOGE-USDT",
	//         "tradeId": "6000001623870",
	//         "orderId": "6000011777113",
	//         "fillPrice": "0.091480000000000000",
	//         "fillSize": "30.000000000000000000",
	//         "fillPnl": null,
	//         "side": "buy",
	//         "fee": "0.030000000000000000",
	//         "ts": "1775213753407",
	//         "brokerId": null,
	//         "feeCurrency": "base_currency"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(trade, "tradeId")
	var marketId *string = this.SafeString(trade, "instId")
	market = this.SafeMarket(marketId, market, "-")
	var symbol any = GetValue(market, "symbol")
	var timestamp *int64 = this.SafeInteger(trade, "ts")
	var price *string = this.SafeString2(trade, "price", "fillPrice")
	var amount *string = this.SafeString2(trade, "size", "fillSize")
	var side *string = this.SafeString(trade, "side")
	var orderId *string = this.SafeString(trade, "orderId")
	var feeCost *string = this.SafeString(trade, "fee")
	var fee any = nil
	var feeCurrency any = DerefScalar(this.SafeString(trade, "feeCurrency"))
	var isSpot bool = !IsEqual(feeCurrency, nil)
	if IsEqual(feeCurrency, nil) {
		feeCurrency = GetValue(market, "settle")
	} else if IsEqual(feeCurrency, "base_currency") {
		feeCurrency = GetValue(market, "base")
	} else if IsEqual(feeCurrency, "quote_currency") {
		feeCurrency = GetValue(market, "quote")
	}
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		}
	}
	if isSpot {
		var spotSymbol any = Add(Add(GetValue(market, "base"), "/"), GetValue(market, "quote"))
		var cost any = this.ParseNumber(Precise.StringMul(price, amount))
		var result map[string]any = map[string]any{
			"info":         trade,
			"timestamp":    timestamp,
			"datetime":     this.Iso8601(timestamp),
			"symbol":       spotSymbol,
			"id":           id,
			"order":        orderId,
			"type":         nil,
			"takerOrMaker": nil,
			"side":         side,
			"price":        this.ParseNumber(price),
			"amount":       this.ParseNumber(amount),
			"cost":         cost,
			"fee": map[string]any{
				"cost":     this.ParseNumber(feeCost),
				"currency": feeCurrency,
			},
		}
		return result
	} else {
		return this.SafeTrade(map[string]any{
			"info":         trade,
			"timestamp":    timestamp,
			"datetime":     this.Iso8601(timestamp),
			"symbol":       symbol,
			"id":           id,
			"order":        orderId,
			"type":         nil,
			"takerOrMaker": nil,
			"side":         side,
			"price":        price,
			"amount":       amount,
			"cost":         nil,
			"fee":          fee,
		}, market)
	}
}

