func (this *Blofin) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	//
	// fetchDeposits
	//
	//     {
	//         "currency": "USDT",
	//         "chain": "TRC20",
	//         "address": "TGfJLtnsh3B9EqekFEBZ1nR14QanBUf5Be",
	//         "txId": "892f4e0c32268b29b2e541ef30d32a30bbf10f902adcc4b1428319ed7c3758fd",
	//         "type": "0",
	//         "amount": "86.975843",
	//         "state": "1",
	//         "ts": "1703163304153",
	//         "tag": null,
	//         "confirm": "16",
	//         "depositId": "36c8e2a7ea184a219de72215a696acaf"
	//     }
	// fetchWithdrawals
	//    {
	//       "currency": "USDT",
	//        "chain": "TRC20",
	//        "address": "TYgB3sVXHPEDQUu288EG1uMFh9Pk2swLgW",
	//        "txId": "1fd5ac52df414d7ea66194cadd9a5b4d2422c2b9720037f66d98207f9858fd96",
	//        "type": "0",
	//        "amount": "9",
	//        "fee": "1",
	//        "feeCurrency": "USDT",
	//        "state": "3",
	//        "clientId": null,
	//        "ts": "1707217439351",
	//        "tag": null,
	//        "memo": null,
	//        "withdrawId": "e0768698cfdf4aee8e54654c3775914b"
	//    }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var typeVar string
	var id any = nil
	var status any = nil
	var withdrawalId *string = this.SafeString(transaction, "withdrawId")
	var depositId *string = this.SafeString(transaction, "depositId")
	var addressTo *string = this.SafeString(transaction, "address")
	var address *string = addressTo
	var tagTo *string = this.SafeString(transaction, "tag")
	if withdrawalId != nil {
		typeVar = "withdrawal"
		id = withdrawalId
		status = this.ParseTransactionWithdrawalStatus(this.SafeString(transaction, "state"))
	} else {
		id = depositId
		typeVar = "deposit"
		status = this.ParseTransactionDepositStatus(this.SafeString(transaction, "state"))
	}
	var currencyId *string = this.SafeString(transaction, "currency")
	var code *string = this.SafeCurrencyCode(currencyId)
	var amount *float64 = this.SafeNumber(transaction, "amount")
	// live history rows carry the DISPLAY-NAME chain identifiers
	// ('Tron (TRC20)', verified live 2026-09-15) even though the doc
	// examples show short forms ('TRC20') - chainIdToNetworkCode parses
	// the parenthesized suffix for the display-name family, and the
	// paren-free ids resolve through the base networkIdToCode with
	// options['networksById']. note the history
	// amount is NET of the fee: a 30 USDT withdrawal-apply lands as
	// amount 29 + fee 1
	var networkId *string = this.SafeString(transaction, "chain")
	var networkCode any = this.ChainIdToNetworkCode(networkId)
	var txid *string = this.SafeString(transaction, "txId")
	var timestamp *int64 = this.SafeInteger(transaction, "ts")
	var feeCurrencyId *string = this.SafeString(transaction, "feeCurrency")
	var feeCode *string = this.SafeCurrencyCode(feeCurrencyId)
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"currency":    code,
		"amount":      amount,
		"network":     networkCode,
		"addressFrom": nil,
		"addressTo":   addressTo,
		"address":     address,
		"tagFrom":     nil,
		"tagTo":       tagTo,
		"tag":         tagTo,
		"status":      status,
		"type":        typeVar,
		"updated":     nil,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"internal":    nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": feeCode,
			"cost":     feeCost,
		},
	}
}
func (this *Blofin) ParseTransactionWithdrawalStatus(status any) *string {
	var statuses map[string]any = map[string]any{
		"0": "pending",
		"2": "failed",
		"3": "ok",
		"4": "failed",
		"6": "pending",
		"7": "pending",
	}
	return this.SafeString(statuses, status, status)
}
